-- Add Rectified Flow, introduced in arXiv 2209.03003.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'rectified-flow',
    'Rectified Flow',
    'Rectified Flow',
    'Rectified flow is a generative modeling and distribution transport method that learns a neural [ODE](/methods/neural-ode) whose velocity field follows straight paths between samples of two distributions, such as Gaussian noise and images. It is trained by a simple least-squares regression of the network''s velocity onto the direction X1 − X0 along linear interpolations between paired points, closely related to [flow matching](/methods/flow-matching). Straight paths are the shortest connections and can be simulated with few Euler steps. The "reflow" procedure, re-training on couplings produced by a previous flow, provably does not increase convex transport costs. Applied recursively, it straightens trajectories so that a single step gives good samples, and the result can then be distilled. The original paper showed results on image generation, image-to-image translation and domain adaptation. Rectified flow later became the training formulation of large text-to-image models: InstaFlow distilled [Stable Diffusion](/methods/stable-diffusion) into one step, and [Scaling Rectified Flow Transformers](/paper/2403.03206) used it for Stable Diffusion 3 with the [MM-DiT](/methods/mmdit) architecture, followed by [FLUX](/methods/flux).',
    'rectified flow, rectified-flow',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2022,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2209.03003'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Flow Straight and Fast: Learning to Generate and Transfer Data with Rectified Flow',
    'https://github.com/gnobitab/RectifiedFlow',
    NULL,
    '[Flow Straight and Fast: Learning to Generate and Transfer Data with Rectified Flow](/paper/2209.03003)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'rectified-flow' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'rectified-flow' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

