INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'rectified-flow citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM rectified_flow_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING rectified_flow_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 135 local citers name the method in title or abstract.
CREATE TEMP TABLE rectified_flow_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'rectified-flow'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        10450, 12602, 20332, 24486, 24897, 31231, 31606, 32083, 32090, 32171, 34049, 34835,
